<template>
  <view class="mpb-page" :style="miniProgramNavigationStyle"><view class="mpb-safe" /><view class="mpb-header"><button class="mpb-back" aria-label="返回" @click="backOrHome('/pages/agent/AgentWithdrawalsPage')">‹</button><image class="mpb-logo" :src="loginLogo" mode="aspectFit" /><view class="mpb-header-copy"><text class="mpb-title">提现详情</text><text class="mpb-subtitle">申请、审核与到账结果</text></view><text class="mpb-role agent">代理商</text></view><view class="mpb-stack"><view v-if="loading" class="mpb-card mpb-empty"><text class="mpb-empty-title">正在加载提现...</text></view><template v-else-if="item"><view class="mpb-hero light"><view class="mpb-hero-top"><view><text class="mpb-hero-label">提现金额</text><text class="mpb-hero-value">{{ formatCurrency(rowNumber(item, 'amountCents', 'amount')) }}</text></view><text :class="['mpb-hero-badge', statusTone(rowString(item, 'status')) === 'success' ? 'success' : 'purple']">{{ statusText(rowString(item, 'status')) }}</text></view><text class="mpb-hero-copy">提现状态来自代理商提现接口，审核结果以运营后台为准。</text></view><view class="mpb-card mpb-list"><view class="mpb-row"><text class="mpb-row-icon">号</text><view class="mpb-row-main"><text class="mpb-row-title">申请编号</text><text class="mpb-row-meta">{{ rowString(item, 'id', 'withdrawalId') }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon green">账</text><view class="mpb-row-main"><text class="mpb-row-title">到账账户</text><text class="mpb-row-meta">{{ rowString(item, 'accountName', 'paymentMethod') || '微信零钱' }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon orange">时</text><view class="mpb-row-main"><text class="mpb-row-title">申请时间</text><text class="mpb-row-meta">{{ formatDate(rowString(item, 'createdAt')) }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon">审</text><view class="mpb-row-main"><text class="mpb-row-title">审核说明</text><text class="mpb-row-meta">{{ rowString(item, 'reviewNote', 'remark', 'reason') || '等待平台审核' }}</text></view><text class="mpb-status">{{ formatDate(rowString(item, 'reviewedAt', 'paidAt')) }}</text></view></view></template><view v-else class="mpb-card mpb-empty"><text class="mpb-empty-title">未找到提现记录</text></view></view></view>
</template>
<script setup lang="ts">
import { ref } from "vue"; import { onLoad } from "@dcloudio/uni-app"; import { api } from "../../api/client"; import { asRecord, backOrHome, formatCurrency, formatDate, rowNumber, rowString, statusText, statusTone, type AnyRecord } from "../../utils/miniProgramBusiness"; import loginLogo from "../../assets/zhiqiyun-logo-transparent.png";
const id=ref(""); const loading=ref(false); const item=ref<AnyRecord|null>(null); async function load(){loading.value=true;try{const payload=asRecord(await api(`/api/v1/channel/withdrawals/${encodeURIComponent(id.value)}`));const detail=asRecord(payload.item);item.value=rowString(detail,"id","withdrawalId")?detail:null;}catch(error){uni.showToast({title:error instanceof Error?error.message:"提现记录加载失败",icon:"none"});}finally{loading.value=false;}} onLoad(options=>{id.value=String(options?.id||"");void load();});
</script>
<style>@import "../../styles/mini-program-business.css";</style>
